type WorldState = Record<string, string>;

const INITIAL_STATE: WorldState = { Fen: "nim" };

function copyState(state: WorldState): WorldState {
  return { ...state };
}

function transitionToPex(
  state: WorldState
): { success: true; newState: WorldState } | { success: false; error: string } {
  if (state.Fen !== "nim") {
    return {
      success: false,
      error: "Fen must be in state 'nim' before it can become 'pex'",
    };
  }

  return { success: true, newState: { ...state, Fen: "pex" } };
}

function resetFen(
  state: WorldState
): { success: true; newState: WorldState } | { success: false; error: string } {
  if (state.Fen !== "pex") {
    return {
      success: false,
      error: "Fen must be in state 'pex' before resetFen can be applied",
    };
  }

  return { success: true, newState: { ...state, Fen: "nim" } };
}

export const protocol: WorldProtocol<WorldState> = {
  reset(): WorldState {
    return copyState(INITIAL_STATE);
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): { success: true; newState: WorldState } | { success: false; error: string } {
    switch (operationDisplayName) {
      case "resetFen":
        return resetFen(state);
      case "activateFen":
      case "advanceFen":
      case "setFenPex":
      case "setFenToPex":
        return transitionToPex(state);
      default:
        return {
          success: false,
          error: `Unknown operation '${operationDisplayName}'`,
        };
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return copyState(state);
  },
};
"}],"workingNote":"Fen を nim から pex へ進める既存系統を維持し、pex の場合だけ resetFen で nim に戻す不変遷移を追加しました。reset と snapshot は状態を複製し、公開 protocol の4メソッドと判別可能な成功・失敗結果を維持しています。"}

